async function fetchProjects() {
  const res = await fetch("/api/projects");
  if (!res.ok) throw new Error(`Projects request failed: ${res.status}`);
  return res.json();
}

const { data, error, refetch } = useQuery({ queryKey: ["projects"], queryFn: fetchProjects });

if (error) {
  return (
    <div role="alert">
      <p>We couldn't load your projects. Check your connection and try again.</p>
      <button onClick={() => refetch()}>Try again</button>
    </div>
  );
}

