async function load() {
  setStatus("loading");
  const res = await fetch("/api/projects");
  if (!res.ok) { setStatus("error"); return; }
  setProjects(await res.json());
  setStatus("done");
}

if (status === "error") {
  return (
    <div>
      <p>Projects failed to load.</p>
      <button onClick={load}>Retry</button>
    </div>
  );
}

useEffect(() => {
  fetch("/api/projects")
    .then((res) => {
      if (!res.ok) throw new Error(String(res.status));
      return res.json();
    })
    .then(setProjects)
